condition.value_template:
{% set room = states('sensor.miaomiaoce_t2_f7cc_temperature') | float(none) %}
{% set battery = states('sensor.miaomiaoce_t2_f7cc_battery_level') | float(0) %}
{% set ac_temp = state_attr('climate.v537_spalniam_2', 'current_temperature') | float(none) %}
{% set outside_venti_raw = states('sensor.miaomiaoce_t2_56fa_temperature') | float(none) %}
{% set outside_venti_battery = states('sensor.miaomiaoce_t2_56fa_battery_level') | float(0) %}
