{% set outside_venti_device = states('sensor.venti_outside_temperature') | float(none) %}
{% set room_sensor_min_battery = states('input_number.bedrooms_room_sensor_min_battery') | float(10) %}
{% set outside_sensor_min_battery = states('input_number.bedrooms_outside_sensor_min_battery') | float(10) %}
{% set room_sensor_stale_hours = states('input_number.bedrooms_room_sensor_stale_hours') | float(5) %}
{% set room_ac_disagreement_threshold = states('input_number.bedrooms_room_ac_disagreement_threshold') | float(1.5) %}
{% set outside_venti_offset = states('input_number.bedrooms_venti_in_offset') | float(2) %}
{% set winter_outside_threshold = states('input_number.bedrooms_winter_outside_threshold') | float(8) %}
{% set summer_outside_threshold = states('input_number.bedrooms_summer_outside_threshold') | float(15) %}
{% set mild_outside_threshold = states('input_number.bedrooms_mild_outside_threshold') | float(28) %}
{% set mild_summer_target = states('input_number.bedrooms_target_temperature') | float(23.9) %}
{% set hot_summer_target = states('input_number.bedrooms_hot_summer_target') | float(24.0) %}
{% set winter_target = states('input_number.bedrooms_winter_target') | float(22) %}
{% set night_summer_target = states('input_number.bedrooms_summer_night_target') | float(30) %}
{% set night_winter_target = states('input_number.bedrooms_winter_night_target') | float(19) %}
{% set night_cooling_start_delta = states('input_number.bedrooms_night_cooling_start_delta') | float(0.4) %}
{% set night_winter_start_delta = states('input_number.bedrooms_night_winter_start_delta') | float(0.5) %}
{% set cooling_start_delta = states('input_number.bedrooms_cooling_start_delta') | float(0.4) %}
{% set winter_start_delta = states('input_number.bedrooms_winter_start_delta') | float(0.5) %}
{% set coil_cooldown_minutes = states('input_number.bedrooms_coil_cooldown_minutes') | float(7) %}
{% set away_ended_at = states('input_datetime.bedrooms_away_ended_at') %}
{% set return_boost_minutes = states('input_number.bedrooms_return_boost_minutes') | float(20) %}
{% set return_boost_active = away_ended_at not in ['unknown', 'unavailable', 'none'] and (as_timestamp(now()) - as_timestamp(away_ended_at, 0)) < (return_boost_minutes * 60) %}
{% set cooling_fan_mode = (states('input_number.bedrooms_return_boost_fan_mode') | int(5)) if return_boost_active else (states('input_number.bedrooms_cooling_fan_mode') | int(2)) %}
{% set bedrooms_night_start_value = states('input_datetime.bedrooms_night_start') if states('input_datetime.bedrooms_night_start') not in ['unknown', 'unavailable', 'none'] else '00:30:00' %}
{% set bedrooms_day_start_value = states('input_datetime.bedrooms_day_start') if states('input_datetime.bedrooms_day_start') not in ['unknown', 'unavailable', 'none'] else '08:30:00' %}
{% set bedrooms_air_clean_start_value = states('input_datetime.bedrooms_air_clean_start') if states('input_datetime.bedrooms_air_clean_start') not in ['unknown', 'unavailable', 'none'] else '03:00:00' %}
{% set bedrooms_air_clean_end_value = states('input_datetime.bedrooms_air_clean_end') if states('input_datetime.bedrooms_air_clean_end') not in ['unknown', 'unavailable', 'none'] else '06:00:00' %}
{% set bedrooms_night_start_parts = bedrooms_night_start_value.split(':') %}
{% set bedrooms_day_start_parts = bedrooms_day_start_value.split(':') %}
{% set bedrooms_air_clean_start_parts = bedrooms_air_clean_start_value.split(':') %}
{% set bedrooms_air_clean_end_parts = bedrooms_air_clean_end_value.split(':') %}
{% set night_start_minutes = (bedrooms_night_start_parts[0] | int) * 60 + (bedrooms_night_start_parts[1] | int) %}
{% set day_start_minutes = (bedrooms_day_start_parts[0] | int) * 60 + (bedrooms_day_start_parts[1] | int) %}
{% set air_clean_start_minutes = (bedrooms_air_clean_start_parts[0] | int) * 60 + (bedrooms_air_clean_start_parts[1] | int) %}
{% set air_clean_end_minutes = (bedrooms_air_clean_end_parts[0] | int) * 60 + (bedrooms_air_clean_end_parts[1] | int) %}
{% set minutes_now = now().hour * 60 + now().minute %}
{% set night_sleep_window = (minutes_now >= night_start_minutes and minutes_now < day_start_minutes) if night_start_minutes < day_start_minutes else (minutes_now >= night_start_minutes or minutes_now < day_start_minutes) %}
{% set night_air_clean_window = (minutes_now >= air_clean_start_minutes and minutes_now < air_clean_end_minutes) if air_clean_start_minutes < air_clean_end_minutes else (minutes_now >= air_clean_start_minutes or minutes_now < air_clean_end_minutes) %}
{% set night_window = night_air_clean_window %}
{% set day_air_clean_window = minutes_now >= day_start_minutes and minutes_now <= 1439 %}
{% if outside_venti_battery > outside_sensor_min_battery and outside_venti_raw is not none %}
  {% set outside_source = 'venti_in_adjusted' %}
  {% set outside = outside_venti_raw - outside_venti_offset %}
{% elif outside_weather is not none %}
  {% set outside_source = 'weather_forecast_home' %}
  {% set outside = outside_weather %}
{% elif outside_venti_device is not none %}
  {% set outside_source = 'venti_device_outside' %}
  {% set outside = outside_venti_device %}
{% else %}
  {% set outside_source = 'none' %}
  {% set outside = none %}
{% endif %}
{% set climate_mode = 'winter' if now().month in [12, 1, 2] else 'summer' %}
{% set bedrooms_room_last_moved = states('input_datetime.bedrooms_room_last_moved') %}
{% set room_stale = bedrooms_room_last_moved in ['unknown', 'unavailable', 'none', ''] or (as_timestamp(now()) - as_timestamp(bedrooms_room_last_moved, 0)) > (room_sensor_stale_hours * 3600) %}
{% set room_healthy = battery > room_sensor_min_battery and room is not none and not room_stale %}
{% set room_ac_conflict = room_healthy and ac_temp is not none and (room - ac_temp) | abs >= room_ac_disagreement_threshold %}
{% if room_healthy and room_ac_conflict %}
  {% set source = 'conflict_worst_case' %}
  {% set effective = ([room, ac_temp] | max) if climate_mode == 'summer' else ([room, ac_temp] | min) if climate_mode == 'winter' else room %}
{% elif room_healthy %}
  {% set source = 'room_sensor' %}
  {% set effective = room %}
{% else %}
  {% set source = 'climate_fallback' %}
  {% set effective = ac_temp %}
{% endif %}
{% set bedrooms_manual_override_until = states('input_datetime.bedrooms_manual_override_until') %}
{% set manual_override_active = is_state('input_boolean.bedrooms_manual_override', 'on') and bedrooms_manual_override_until not in ['unknown', 'unavailable', 'none'] and as_timestamp(bedrooms_manual_override_until, 0) > as_timestamp(now()) %}
{% set allow_night_cooling = is_state('input_boolean.bedrooms_allow_night_cooling', 'on') %}
{% set away_p1 = states('person.krasimir_koev') %}
{% set away_p2 = states('person.ema_yosifova') %}
{% set away_by_presence = away_p1 == 'not_home' and away_p2 == 'not_home' %}
{% set m1 = states('binary_sensor.motion01') %}
{% set m1_changed = states.binary_sensor.motion01.last_changed %}
{% set m2 = states('binary_sensor.motion03') %}
{% set m2_changed = states.binary_sensor.motion03.last_changed %}
{% set m3 = states('binary_sensor.motion04spalniam') %}
{% set m3_changed = states.binary_sensor.motion04spalniam.last_changed %}
{% set motion_quiet_30m = (m1 == 'off' and (as_timestamp(now()) - as_timestamp(m1_changed)) >= 1800) and (m2 == 'off' and (as_timestamp(now()) - as_timestamp(m2_changed)) >= 1800) and (m3 == 'off' and (as_timestamp(now()) - as_timestamp(m3_changed)) >= 1800) %}
{% set away_by_no_motion = day_air_clean_window and motion_quiet_30m %}
{% set allow_away_saving = is_state('input_boolean.bedrooms_allow_away_saving', 'on') %}
{% set away = allow_away_saving and (away_by_presence or away_by_no_motion) %}
{% set away_relax_delta = (states('input_number.bedrooms_away_relax_delta') | float(3)) if away else 0 %}
{% set day_summer_target = mild_summer_target if climate_mode == 'summer' and outside is not none and outside < mild_outside_threshold else hot_summer_target if climate_mode == 'summer' else none %}
{% set summer_night_window = (now().hour > 19 or (now().hour == 19 and now().minute >= 30) or now().hour < 8 or (now().hour == 8 and now().minute < 30)) %}
{% set target = night_summer_target if climate_mode == 'summer' and summer_night_window else day_summer_target if climate_mode == 'summer' else night_winter_target if night_sleep_window and climate_mode == 'winter' else winter_target if climate_mode == 'winter' else none %}
{% set active_cooling_start_delta = cooling_start_delta + away_relax_delta %}
{% set active_winter_start_delta = (night_winter_start_delta if night_sleep_window else winter_start_delta) + away_relax_delta %}
{% set learned_overshoot = [0, [1, states('input_number.bedrooms_cooling_overshoot') | float(0.2)] | min] | max %}
{% set cooling_stop_room_temp = states('input_number.bedrooms_cooling_stop_room_temp') | float(0) %}
{% set error = effective - target if effective is not none and target is not none else none %}
{% set dynamic_setpoint = ([16, [31, ((ac_temp - error) * 2) | round(0) / 2] | min] | max) if ac_temp is not none and error is not none else none %}
{{ not manual_override_active }}

